(()=>{const config=window.GroundhoggUTM;if(!config||!config.params){return}const SOURCE="groundhogg-plugin";const LEGACY_SOURCES=["wp-plugins","plugin","admin-menu"];const isGroundhoggIo=host=>host==="groundhogg.io"||host.endsWith(".groundhogg.io");const slug=value=>String(value??"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").substring(0,60);const CORE_SCREENS={"plugins.php":"plugins","plugin-install.php":"plugin-install","update-core.php":"update-core","index.php":"wp-dashboard","profile.php":"profile","users.php":"users"};const screenCampaign=()=>{const query=new URLSearchParams(window.location.search);const page=query.get("page")??"";if(page==="groundhogg"||page.startsWith("gh_")){let parts=[page==="groundhogg"?"dashboard":page.replace(/^gh_/,"")];for(let key of["tab","action"]){if(query.get(key)){parts.push(query.get(key))}}return slug(parts.join("-"))}let file=window.location.pathname.split("/").pop()||"index.php";return CORE_SCREENS[file]??"other-screen"};const utmUrl=(href,{content="",campaign="",medium=""}={})=>{let url;try{url=new URL(href,window.location.href)}catch(e){return href}if(!["http:","https:"].includes(url.protocol)||!isGroundhoggIo(url.hostname)){return href}let source=url.searchParams.get("utm_source");let changed=false;if(LEGACY_SOURCES.includes(source)){content=content||url.searchParams.get("utm_campaign")||"";for(let key of[...url.searchParams.keys()].filter(key=>key.startsWith("utm_"))){url.searchParams.delete(key)}changed=true}else if(source&&source!==SOURCE){return href}let params={...config.params,utm_campaign:slug(campaign)||config.params.utm_campaign||screenCampaign()};if(medium){params.utm_medium=slug(medium)}if(content){params.utm_content=slug(content)}for(let[key,value]of Object.entries(params)){if(value&&!url.searchParams.has(key)){url.searchParams.set(key,value);changed=true}}return changed?url.toString():href};const closestData=(el,key)=>el.closest(`[data-utm-${key}]`)?.getAttribute(`data-utm-${key}`)??"";const SKIP='[contenteditable]:not([contenteditable="false"]), #builder-content, [data-utm-skip]';const tagAnchor=link=>{let href=link.getAttribute("href");if(!href||!href.includes("groundhogg.io")||link.closest(SKIP)){return}let tagged=utmUrl(href,{content:closestData(link,"content"),campaign:closestData(link,"campaign"),medium:closestData(link,"medium")});if(tagged!==href){link.setAttribute("href",tagged)}};const SELECTOR='a[href*="groundhogg.io"]';const tagWithin=node=>{if(node.nodeType!==Node.ELEMENT_NODE){return}if(node.matches(SELECTOR)){tagAnchor(node)}node.querySelectorAll(SELECTOR).forEach(tagAnchor)};tagWithin(document.documentElement);new MutationObserver(records=>{for(let record of records){if(record.type==="attributes"){tagWithin(record.target);continue}record.addedNodes.forEach(tagWithin)}}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:["href"]});const tagLink=e=>{let link=e.composedPath().find(el=>el instanceof HTMLAnchorElement&&el.hasAttribute("href"));if(link){tagAnchor(link)}};for(let event of["mousedown","click","auxclick","contextmenu"]){document.addEventListener(event,tagLink,true)}config.url=utmUrl})();